<?php get_header(); ?><main id="main-content" class="slateframe-main"><header class="slateframe-page-header"><div class="slateframe-shell"><h1 class="slateframe-page-title"><?php printf(esc_html__('Search results for: %s','slateframe'),'<span>'.esc_html(get_search_query()).'</span>'); ?></h1><?php get_search_form(); ?></div></header><div class="slateframe-shell slateframe-grid"><?php if(have_posts()):while(have_posts()):the_post();?><article <?php post_class('slateframe-card'); ?>><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></article><?php endwhile;else:?><section><h2><?php esc_html_e('No results','slateframe'); ?></h2><p><?php esc_html_e('Try a different search term.','slateframe'); ?></p></section><?php endif;?></div><div class="slateframe-shell"><?php slateframe_pagination(); ?></div></main><?php get_footer(); ?>